def terminal_option_values(terminal_cents,strike_cents,premium_cents,multiplier,kind):
    if any(type(v) is not int or not 0<=v<=1000000 for v in (terminal_cents,strike_cents,premium_cents)):
        raise ValueError("expected bounded nonnegative integer per-unit cents")
    if type(multiplier) is not int or not 1<=multiplier<=1000 or kind not in ("call","put"):
        raise ValueError("expected explicit bounded multiplier and call/put")
    per_unit=max(terminal_cents-strike_cents,0) if kind=="call" else max(strike_cents-terminal_cents,0)
    payoff=multiplier*per_unit
    premium_paid=multiplier*premium_cents
    return payoff,payoff-premium_paid  # zero financing/fees, hold long to expiry only

for spot in (8000,10000,12000):
    print(spot,terminal_option_values(spot,10000,700,10,"call"),terminal_option_values(spot,10000,700,10,"put"))
print(terminal_option_values(10500,10000,700,10,"call"))
